#if UNITY_EDITOR
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

// Real native inputs and raycast clicks. Large-value formatting sample is an adapter.
public static class QuantityAllocationPresentationValidation
{
    const string Base=".tools/quantity-allocation-1006/ui",Native=".tools/quantity-allocation-1006/native";
    public static string Output {get;private set;}
    public static bool Running {get;private set;}
    [Serializable] class Meta {public string folder,status,runtimeHash;}
    static Transform Root=>GameObject.Find("Canvas").transform;
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static string Hash(string file){using var h=SHA256.Create();return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(file))).Replace("-","").ToLowerInvariant();}
    static string Folder(string name){var p=Native+"/"+name+"-result.json";var m=JsonUtility.FromJson<Meta>(File.ReadAllText(p));Check(m.status=="PASS"&&m.runtimeHash==JsonUtility.FromJson<Meta>(File.ReadAllText("ForgeRuntime/runtime.json")).runtimeHash,"Incomplete/stale native "+name);File.Copy(p,Output+"/inputs/"+name+"-meta.json",true);return m.folder;}
    static ForgeSeatView Read(string name,string label){string p=Path.Combine(Folder(name),label+".json");File.Copy(p,Output+"/inputs/"+name+"-"+label+".json",true);File.AppendAllText(Output+"/input-hashes.tsv",name+"/"+label+"\t"+Hash(p)+"\n");return JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p));}
    static IEnumerator Frame(){yield return new WaitForSecondsRealtime(.2f);yield return new WaitForEndOfFrame();Canvas.ForceUpdateCanvases();}
    static void Clean(){foreach(var p in UnityEngine.Object.FindObjectsByType<ForgeBattlefieldCardPointer>(FindObjectsSortMode.None)){p.ResetHover();p.enabled=false;}}
    static void Click(Button button){Check(button!=null&&button.interactable,"Missing/disabled "+button?.name);var rect=(RectTransform)button.transform;foreach(float y in new[]{.5f,.25f,.75f})foreach(float x in new[]{.5f,.12f,.88f}){var local=new Vector2(Mathf.Lerp(rect.rect.xMin,rect.rect.xMax,x),Mathf.Lerp(rect.rect.yMin,rect.rect.yMax,y));var p=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(local)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(p,hits);if(hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==button){ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,p,ExecuteEvents.pointerClickHandler);return;}}throw new Exception("Ray blocked "+button.name);}
    static Rect Bounds(Transform t){var c=new Vector3[4];((RectTransform)t).GetWorldCorners(c);return Rect.MinMaxRect(c.Min(p=>p.x),c.Min(p=>p.y),c.Max(p=>p.x),c.Max(p=>p.y));}
    static void DockBounds(Transform dock){foreach(var b in dock.GetComponentsInChildren<Button>()){Check(!Bounds(b.transform).Overlaps(Bounds(Root.Find("CornerCluster/ControlRow/PhaseTrack"))),"Phase covered");Check(!Bounds(b.transform).Overlaps(Bounds(Root.Find("PriorityControlMode"))),"AUTO covered");}var value=dock.Find("NumericValue").GetComponent<Text>();Check(!value.resizeTextForBestFit&&value.preferredWidth<=value.rectTransform.rect.width,"Numeric text overflow/shrink");foreach(string n in new[]{"Decrease","Increase","ConfirmValue"})Check(!Bounds(value.transform).Overlaps(Bounds(dock.Find(n))),"Number overlaps "+n);}
    static IEnumerator Shot(string lang,string label){if(lang!="zh-CN")yield break;ScreenCapture.CaptureScreenshot(Output+"/"+label+".png");yield return Frame();}
    public static void Run(){Check(Application.isPlaying&&!Running,"Play required/already running");Running=true;Output=Base+"/"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffffffZ");Directory.CreateDirectory(Output+"/inputs");File.WriteAllText(Base+"/latest.txt",Output);File.WriteAllText(Output+"/result.txt","RUNNING");File.WriteAllText(Output+"/producer-hashes.tsv",string.Join("\n",new[]{"Assets/Scripts/Editor/QuantityAllocationPresentationValidation.cs","Assets/Scripts/UI/ForgeBattlefieldController.Allocation.cs","Assets/Scripts/UI/ForgeBattlefieldController.Notices.cs","Tools/ForgeBridge/NativePatches.json"}.Select(p=>p+"\t"+Hash(p)))+"\n");var runner=new GameObject("QuantityAllocationValidation");runner.AddComponent<Host>().StartCoroutine(Guard(Exercise(),runner));}
    sealed class Host:MonoBehaviour{}
    static IEnumerator Guard(IEnumerator e,GameObject runner){Exception error=null;while(true){bool more=false;object current=null;try{more=e.MoveNext();if(more)current=e.Current;}catch(Exception ex){error=ex;break;}if(!more)break;if(current is IEnumerator nested){yield return GuardChild(nested,ex=>error=ex);if(error!=null)break;}else yield return current;}try{(e as IDisposable)?.Dispose();}catch(Exception ex){error??=ex;}File.WriteAllText(Output+"/result.txt",error==null?"PASS: native counter/shield/mana/different-color allocation replay and actual clicks: amount/reset/confirm, native lower/upper/total gates and exact IDs, font/window stability, existing mana symbols and titles in three locales; no network claim.":"FAIL\n"+error);Running=false;UnityEngine.Object.Destroy(runner);}
    static IEnumerator GuardChild(IEnumerator e,Action<Exception> fail){while(true){bool more=false;object current=null;try{more=e.MoveNext();if(more)current=e.Current;}catch(Exception ex){fail(ex);break;}if(!more)break;if(current is IEnumerator nested)yield return GuardChild(nested,fail);else yield return current;}}
    static IEnumerator Exercise(){var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>()??new GameObject("QuantityAllocationBattlefield").AddComponent<ForgeBattlefieldController>();bool enabled=ui.enabled;ui.enabled=false;string locale=GamePreferences.Language;var module=EventSystem.current.currentInputModule;bool input=module!=null&&module.enabled;if(module!=null)module.enabled=false;var notices=UnityEngine.Object.FindObjectsByType<ForgeBattlefieldMigrationNotice>(FindObjectsSortMode.None);var flags=notices.Select(n=>n.enabled).ToArray();foreach(var n in notices)n.enabled=false;
        try{foreach(string lang in new[]{"zh-CN","en-US","ja-JP"}){
            int revision=GamePreferences.Revision;bool change=GamePreferences.Language!=lang;GamePreferences.SetLanguage(lang);float until=Time.realtimeSinceStartup+20;while((!GamePreferences.Ready||change&&revision==GamePreferences.Revision)&&Time.realtimeSinceStartup<until)yield return null;Check(GamePreferences.Ready,"Locale unavailable");yield return Frame();File.AppendAllText(Output+"/steps.log","requested="+lang+" loaded="+GamePreferences.Language+"\n");
            foreach(string name in new[]{"counter-division","shield-division","mana-combo","mana-different","shield-on-damage"})foreach(string label in new[]{"allocation-before-subtract","allocation-before-reset","allocation-confirm"}){
                var v=Read(name,label);int calls=0,last=-1;ui.Present(null,1,false,null,null,"");ui.Present(v,1,true,i=>{calls++;last=i;},null,"");yield return Frame();Clean();var panel=Root.Find("DamageAllocation");Check(panel!=null&&panel.gameObject.activeInHierarchy,"Allocation missing");var values=v.request.allocations;Check(panel.GetComponentsInChildren<RectTransform>().Count(t=>t.name.StartsWith("Recipient_"))==values.Length,"Recipient mismatch");
                string title=name.StartsWith("mana")?(lang=="zh-CN"?"分配法术力":lang=="ja-JP"?"マナを割り振る":"Assign mana"):name.StartsWith("counter")?(lang=="zh-CN"?"分配指示物":lang=="ja-JP"?"カウンターを割り振る":"Assign counters"):(lang=="zh-CN"?"分配预防伤害":lang=="ja-JP"?"ダメージ軽減を割り振る":"Assign damage prevention");Check(panel.Find("Title").GetComponent<Text>().text==title,"Allocation locale");Check(panel.GetComponentsInChildren<Text>().All(t=>!t.resizeTextForBestFit),"Font auto size");
                foreach(var value in values){var tile=panel.GetComponentsInChildren<RectTransform>().Single(t=>t.name=="Recipient_"+value.id);Check(tile.Find("Amount").GetComponent<Text>().text==value.amount.ToString(),"Amount mismatch");foreach(string direction in new[]{"Plus","Minus"})Check(tile.Find(direction).GetComponent<Button>().interactable==(ui.OptionIndex((direction=="Plus"?"amount-add:":"amount-sub:")+value.id)>=0),"Native allocation gate mismatch");
                    if(name.StartsWith("mana")){var symbol=tile.Find("ManaSymbol").GetComponent<TMPro.TextMeshProUGUI>();symbol.ForceMeshUpdate();Check(symbol.textInfo.characterCount==1&&!symbol.text.Contains("{"),"Mana symbol absent");var glyph=symbol.textInfo.characterInfo[0];Check(glyph.elementType==TMPro.TMP_TextElementType.Sprite&&glyph.isVisible&&glyph.textElement is TMPro.TMP_SpriteCharacter&&glyph.textElement.unicode==symbol.text[0]&&symbol.spriteAsset==CardSymbolText.Atlas,"Wrong/invisible mana glyph");Check(tile.Find("Name").GetComponent<Text>().text=="","Native enum exposed as text");}
                    else Check(tile.Find("Art").GetComponent<RawImage>().texture!=null,"Recipient art missing");
                }
                var confirm=panel.Find("Confirm").GetComponent<Button>();Check(confirm.interactable==(v.request.remainingCount==0),"Confirmation total mismatch");Check(!panel.Find("Skip").gameObject.activeSelf&&ui.OptionIndex("cancel")<0,"Invented allocation cancellation");var fonts=panel.GetComponentsInChildren<Text>().Select(t=>t.fontSize).ToArray();ui.ViewBattlefield();yield return Frame();Check(panel.GetComponentInParent<CanvasGroup>().alpha==0&&!ui.TrySubmitPresentedOption(ui.OptionIndex("reset-amount"),v.request.requestId),"Hidden allocation submits");ui.RestoreBattlefieldWindows();yield return Frame();Check(fonts.SequenceEqual(panel.GetComponentsInChildren<Text>().Select(t=>t.fontSize))&&calls==0,"Restore font/submission");
                string id=label=="allocation-before-reset"?"reset-amount":label=="allocation-confirm"?"confirm-amount":v.request.options.First(o=>o.id.StartsWith("amount-sub:")).id;int expected=ui.OptionIndex(id);Check(!ui.TrySubmitPresentedOption(expected,v.request.requestId-1),"Stale allocation accepted");Button button=id=="reset-amount"?panel.Find("Reset").GetComponent<Button>():id=="confirm-amount"?confirm:panel.GetComponentsInChildren<RectTransform>().Single(t=>t.name=="Recipient_"+id.Split(':')[1]).Find("Minus").GetComponent<Button>();yield return Shot(lang,name+"-"+label);Click(button);Check(calls==1&&last==expected&&!ui.TrySubmitPresentedOption(expected,v.request.requestId),"Allocation identity/duplicate");
                ui.Present(null,1,false,null,null,"");ui.Present(v,1,true,i=>{calls++;last=i;},null,"");yield return Frame();Clean();var add=v.request.options.FirstOrDefault(o=>o.id.StartsWith("amount-add:"));if(add!=null){Click(panel.GetComponentsInChildren<RectTransform>().Single(t=>t.name=="Recipient_"+add.id.Split(':')[1]).Find("Plus").GetComponent<Button>());Check(calls==2&&last==ui.OptionIndex(add.id),"Allocation add ID");}
                ui.Present(v,1,false,i=>calls++,null,"");yield return Frame();Check(panel.GetComponentsInChildren<Button>().All(b=>!b.interactable)&&!ui.TrySubmitPresentedOption(expected,v.request.requestId),"Viewer allocation enabled");
                ui.Present(Read(name,"resolved"),1,false,null,null,"");yield return Frame();Check(!panel.gameObject.activeInHierarchy,"Allocation retained at next priority");
            }
            File.AppendAllText(Output+"/steps.log","PASS allocation native inputs/clicks and symbols "+lang+"\n");
        }}finally{ui.Present(null,1,false,null,null,"");ui.enabled=enabled;GamePreferences.SetLanguage(locale);if(module!=null)module.enabled=input;for(int i=0;i<notices.Length;i++)if(notices[i]!=null)notices[i].enabled=flags[i];}
    }
}
#endif
